using System.Text.Json;
using EmberLighthouse.Core;
using EmberLighthouse.Creatures;
using EmberLighthouse.Items;
using EmberLighthouse.Persistence;
using EmberLighthouse.World;
public static class ExpansionTests
{
    public static void Run(Catalog catalog,CreatureDef[] defs,Action<string,Action> test,string root)
    {
        void Check(bool ok,string text){if(!ok)throw new Exception(text);}
        test("expansion covers approved equipment and species without duplicate mineral branches",()=>{
            foreach(string mat in new[]{"leather","copper","chain","iron","gold","crystal","ember"})for(int slot=0;slot<4;slot++){var id=mat+"_"+new[]{"helmet","chestplate","leggings","boots"}[slot];Check(catalog.Items[id].ArmorSlot==slot,"missing armor "+id);}
            Check(catalog.Items.Values.Count(d=>d.Use=="armor")==30&&catalog.Items.Values.Count(d=>d.Use=="animal_armor")==7&&defs.Length==26,"approved catalog mismatch");Check(!catalog.Items.Keys.Any(id=>id.Contains("diamond")||id.Contains("netherite")),"duplicate ore branches");
            foreach(string id in new[]{"shears","iron_hoe","fishing_rod","bucket","bone","bone_meal","sugar_cane","paper","pumpkin","pumpkin_seed","melon","melon_seed","apple","raw_cod","cooked_cod","bowl","mushroom_stew","golden_apple","gold_ore","gold_ingot","glass_bottle","brewing_stand","healing_potion","fire_resistance_potion"})Check(catalog.Items.ContainsKey(id),"preview item absent "+id);
            var available=new HashSet<string>(catalog.Items.Values.Where(d=>d.Block&&d.Use is not("seed")).Select(d=>d.Id));available.UnionWith(defs.Select(d=>d.Drop));available.UnionWith(["grain","carrot","potato","raw_iron","crystal","coal","copper_ore","fiber","apple","raw_cod","egg","turtle_scute","armadillo_scute","feather"]);
            bool changed=true;while(changed){changed=false;if(available.Contains("glass_bottle"))changed|=available.Add("water_bottle");foreach(var r in catalog.Recipes.Values)if(r.Inputs.Keys.All(available.Contains))changed|=available.Add(r.Output);}foreach(var r in catalog.Recipes.Values.Where(r=>r.Id is "elytra" or "wolf_armor" or "turtle_shell" or "healing_potion" or "fire_resistance_potion"||r.Id.StartsWith("ember_")||r.Id.EndsWith("_horse_armor")))Check(available.Contains(r.Output),"unobtainable content "+r.Output);
        });
        test("armor effects, mixed wear, enchantment and upgrade preserve item attributes",()=>{
            var s=new WorldSnapshot();var w=new WorldState(catalog,s);for(int i=0;i<4;i++)s.Equipment.Slots[i]=new("ember_"+new[]{"helmet","chestplate","leggings","boots"}[i],1);
            Check(ArmorTraits.Knockback(s)==.6&&Math.Abs(ArmorTraits.HeatDamage(s,10)-4)<.001&&ArmorTraits.Toughness(s)==3,"ember identity missing");s.Equipment.Slots[0]=new("leather_helmet",1){Dye="red",Protection=2,Unbreaking=3};Check(ArmorTraits.Mobility(s)>1&&ArmorTraits.Warmth(s)>0,"leather identity missing");
            var original=s.Equipment.Slots[0]!.Copy();Check(Inventory.Move(s.Equipment,0,s.Inventory,0,1,catalog),"move");s.Inventory.Sort(catalog);Inventory.Click(s.Inventory,0,null,false,catalog,out var cursor);Check(cursor!.Dye==original.Dye&&cursor.Protection==2&&cursor.Unbreaking==3,"click lost attributes");Inventory.Click(s.Inventory,0,cursor,false,catalog,out _);Check(s.Copy().Inventory.Slots[0]!.Dye=="red","copy lost dye");
            s.Inventory=new();s.Inventory.Slots[0]=new("gold_helmet",1);s.Inventory.Add("crystal",2,catalog);s.Experience=40;Check(ArmorTraits.Enchant(w,s.Inventory,0,true,out _)&&s.Inventory.Slots[0]!.Protection==2&&s.Experience==34&&s.Inventory.Count("crystal")==1,"gold enchant bonus or payment");
            s.Inventory=new();s.Inventory.Slots[0]=new("crystal_helmet",1,40){Protection=2,Unbreaking=1};s.Inventory.Add("ember_alloy",3,catalog);Check(s.Inventory.Craft(catalog.Recipes["ember_helmet"],catalog,out _)&&s.Inventory.Slots.First(i=>i?.Id=="ember_helmet")!.Protection==2,"upgrade lost enchantment");
        });
        test("potions and food return containers atomically, expire and do not stack",()=>{
            var s=new WorldSnapshot{Health=35,Hunger=30};var w=new WorldState(catalog,s);s.Inventory.Slots[0]=new("healing_potion",2);Check(w.UseExpansion(s.Inventory,0,null,null,out _)&&s.Health==65&&s.Inventory.Count("glass_bottle")==1&&s.Inventory.Count("healing_potion")==1,"healing or return");Check(!w.UseExpansion(s.Inventory,0,null,null,out _)&&s.Health==65,"cooldown bypass");w.Advance(8);Check(w.UseExpansion(s.Inventory,0,null,null,out _)&&s.Health==95,"cooldown never ended");
            s.Inventory.Slots[0]=new("golden_apple",2);w.Advance(8);Check(w.UseExpansion(s.Inventory,0,null,null,out _)&&s.Effects.Shield==16,"apple missing effect");w.Advance(8);Check(w.UseExpansion(s.Inventory,0,null,null,out _)&&s.Effects.Shield==16,"shield stacked");w.Advance(90);Check(s.Effects.Shield==0,"shield never expired");
            s.Inventory.Slots[0]=new("fire_resistance_potion",1);Check(w.UseExpansion(s.Inventory,0,null,null,out _)&&ArmorTraits.HeatDamage(s,8)==2,"fire potion");s.Inventory.Slots[0]=new("milk_bucket",1);Check(w.UseExpansion(s.Inventory,0,null,null,out _)&&s.Effects.FireUntil==0&&s.Inventory.Count("bucket")==1,"milk didn't clear and return");s.Inventory.Slots[0]=new("mushroom_stew",1);Check(w.UseExpansion(s.Inventory,0,null,null,out _)&&s.Inventory.Count("bowl")==1,"stew discarded bowl");
            s.Inventory=new();for(int i=0;i<36;i++)s.Inventory.Slots[i]=new("stone",64);s.Inventory.Slots[0]=new("healing_potion",2);s.Effects.DrinkReady=0;string before=JsonSerializer.Serialize(s);Check(!w.UseExpansion(s.Inventory,0,null,null,out _)&&JsonSerializer.Serialize(s)==before,"overflow committed consumable/effect");
        });
        test("hoe, new crops, water, fertilizer and cane form renewable harvest loops",()=>{
            var s=new WorldSnapshot();var w=new WorldState(catalog,s);var p=new Cell(700,70,700);w.Set(p,catalog.Number("dirt"));w.Set(p+new Cell(0,1,0),0);s.Inventory.Slots[0]=new("iron_hoe",1);Check(w.UseExpansion(s.Inventory,0,p,null,out _)&&w.Get(p)==catalog.Number("farmland"),"hoe");s.Inventory.Add("pumpkin_seed",1,catalog);Check(w.Plant(p,"pumpkin_seed",out _),"pumpkin seed");s.Inventory.Slots[0]=new("bone_meal",2);Check(w.UseExpansion(s.Inventory,0,p+new Cell(0,1,0),null,out _),"fertilizer");w.Advance(200);Check(w.Harvest(p+new Cell(0,1,0),out _)&&s.Graves.Sum(g=>g.Items.Count("pumpkin"))==3,"pumpkin loop");
            var water=p+new Cell(1,0,0);w.Set(water,catalog.Number("water"));s.Inventory.Slots[0]=new("bucket",1);Check(w.UseExpansion(s.Inventory,0,water,null,out _)&&s.Inventory.Count("water_bucket")==1,"bucket fill");s.Inventory.Slots[0]=new("glass_bottle",1);Check(w.UseExpansion(s.Inventory,0,water,null,out _)&&s.Inventory.Count("water_bottle")==1,"bottle fill");w.Set(p,catalog.Number("dirt"));s.Inventory.Slots[0]=new("sugar_cane",1);Check(w.UseExpansion(s.Inventory,0,p,null,out _),"cane plant");w.Advance(300);Check(w.Harvest(p+new Cell(0,1,0),out _)&&s.Graves.Sum(g=>g.Items.Count("sugar_cane"))>=3,"cane lost material");
        });
        test("animal interactions, cooldowns, breeding and turtle scutes persist across reload",()=>{
            var s=new WorldSnapshot{Position=[700,70,700]};var w=new WorldState(catalog,s);var cow=new CreatureState{Kind="cow",Position=[701,70,700],Health=40};s.Creatures.Add(cow);s.Inventory.Slots[0]=new("bucket",1);Check(LifeRules.Interact(w,cow,s.Inventory,0,out _)&&s.Inventory.Count("milk_bucket")==1,"milking");s.Inventory.Slots[0]=new("bucket",1);Check(!LifeRules.Interact(w,cow,s.Inventory,0,out _),"milk cooldown bypass");
            var sheep=new CreatureState{Kind="sheep",Position=[700,70,701],Health=28};s.Creatures.Add(sheep);s.Inventory.Slots[0]=new("shears",1);Check(LifeRules.Interact(w,sheep,s.Inventory,0,out _)&&s.Graves.Sum(g=>g.Items.Count("wool"))==3&&!LifeRules.Interact(w,sheep,s.Inventory,0,out _),"shearing/cooldown");
            var a=new CreatureState{Kind="turtle",Position=[700,70,700],Health=35};var b=new CreatureState{Kind="turtle",Position=[701,70,700],Health=35};s.Creatures.AddRange([a,b]);s.Inventory.Slots[0]=new("reed",2);Check(LifeRules.Interact(w,a,s.Inventory,0,out _)&&LifeRules.Interact(w,b,s.Inventory,0,out _),"feeding");w.Advance(1);var baby=s.Creatures.Single(c=>c.BabyUntil>s.Time);Check(baby.ScutePending&&baby.Persistent,"offspring state");var loaded=JsonSerializer.Deserialize<WorldSnapshot>(JsonSerializer.Serialize(s),Catalog.JsonOptions)!;var w2=new WorldState(catalog,loaded);w2.Advance(360);Check(loaded.Graves.Sum(g=>g.Items.Count("turtle_scute"))==1,"scute missing");w2.Advance(360);Check(loaded.Graves.Sum(g=>g.Items.Count("turtle_scute"))==1,"scute duplicate");
        });
        test("tamed companions retain armor wear, saddle and identity in backup and distant population",()=>{
            var s=new WorldSnapshot{Position=[0,39,0]};var w=new WorldState(catalog,s);var wolf=new CreatureState{Kind="wolf",Health=35,Position=[1,39,0]};s.Creatures.Add(wolf);s.Inventory.Slots[0]=new("bone",1);Check(LifeRules.Interact(w,wolf,s.Inventory,0,out _)&&wolf.Tamed,"taming");s.Inventory.Slots[0]=new("wolf_armor",1,33);Check(LifeRules.Interact(w,wolf,s.Inventory,0,out _)&&wolf.Armor?.Durability==33,"equip repaired armor");wolf.Sitting=true;wolf.Position=[500,39,500];s.Population.Initialized=true;s.Population.NextSpawnTime=0;CreaturePopulation.Tick(w,defs,new(0,39,0),_=>false);Check(s.Creatures.Contains(wolf),"pet despawned");
            var horse=new CreatureState{Kind="horse",Health=65,Position=[1,39,0]};s.Creatures.Add(horse);s.Inventory.Slots[0]=new("apple",1);Check(LifeRules.Interact(w,horse,s.Inventory,0,out _),"horse taming");s.Inventory.Slots[0]=new("saddle",1);Check(LifeRules.Interact(w,horse,s.Inventory,0,out _)&&horse.Saddled,"saddle");
            var store=new SaveStore(Path.Combine(root,"expansion-pets","worlds"),catalog);store.Save(s);string key=Path.GetFileName(store.Backup(s.WorldId));var restored=store.Load(store.RestoreBackup(key)).Snapshot;Check(restored.Creatures.Single(c=>c.Id==wolf.Id).Armor?.Durability==33&&restored.Creatures.Single(c=>c.Id==wolf.Id).Sitting&&restored.Creatures.Single(c=>c.Id==horse.Id).Saddled,"companion backup loss");
        });
        test("generator6 keeps old terrain baselines and supplies new mineral and aquatic habitats",()=>{
            var current=new Terrain(42,catalog);var old=new Terrain(42,catalog,5);int gold=0;for(int x=0;x<32;x++)for(int z=0;z<32;z++)for(int y=5;y<28;y++){var p=new Cell(x,y,z);if(catalog.Id(current.Get(p))=="gold_ore"){gold++;Check(catalog.Id(old.Get(p)) is "stone" or "basalt","unexpected ore replacement");}}
            Check(gold>0,"no gold deposits");var s=new WorldSnapshot{Seed=16};var w=new WorldState(catalog,s);var species=new HashSet<string>();for(uint i=0;i<500;i++)species.Add(CreaturePopulation.KindAt(w,new(0,37,0),i)!);Check(species.Count>=4,"uniform wildlife");s.Time=900;for(uint i=0;i<100;i++)species.Add(CreaturePopulation.KindAt(w,new(0,37,0),i)!);Check(species.Contains("creeper")&&species.Contains("skeleton"),"hostile variety missing");
        });
        test("format5 migrates expansion without changing existing edits, equipment or progression",()=>{
            var s=new WorldSnapshot{FormatVersion=5,GeneratorVersion=5};s.Equipment.Slots[1]=new("iron_chestplate",1,63){HeatLining=true};s.Mainline.Proofs.Add("mine");s.Changes["1,60,1"]="chest";Check(SaveMigrations.ToCurrent(s)&&s.FormatVersion==WorldSnapshot.CurrentFormat&&s.GeneratorVersion==5&&s.Equipment.Slots[1]?.HeatLining==true&&s.Mainline.Proofs.Contains("mine"),"migration changed old state");new WorldState(catalog,s);var bad=s.Copy();bad.Effects.Shield=double.NaN;bool rejected=false;try{new WorldState(catalog,bad);}catch(InvalidOperationException){rejected=true;}Check(rejected,"invalid effects accepted");
        });
    }
}

